"""One finite guest call for new parent callbacks/focus/lifecycle; no passed child replay."""
from pathlib import Path
import argparse,json,re,hashlib
from driver import ps,q
r=Path(__file__).resolve().parents[2];p=argparse.ArgumentParser();p.add_argument('--stage',type=Path,required=True);p.add_argument('--output',type=Path,required=True);p.add_argument('--remaining-only',action='store_true');a=p.parse_args();assert json.loads((r/'docs/replica/ENVIRONMENT_LEASE.json').read_text())['resources']['windows']['owner']=='preflight';v=json.loads(a.stage.read_text());assert v['owner']=='preflight'and v['component']=='preflightpage'and re.fullmatch(r'DBMV-Isolated-preflight-preflightpage-[0-9a-f]{32}',v['guestFolder']);a.output.mkdir(parents=True,exist_ok=True)
cs=r/'tools/WindowsControl/owned_preflight_page_input.cs';digest=hashlib.sha256(cs.read_bytes()).hexdigest();name='preflight-preflightpage-input-'+digest+'.cs';(r/'artifacts/replica/windows-download'/name).write_bytes(cs.read_bytes());dll='OwnedPreflightPageInput-'+digest+'.dll';base="$app=Join-Path (Join-Path $env:TEMP "+q(v['guestFolder'])+") 'app';"
code=base+"$dll=Join-Path $app "+q(dll)+";if(!(Test-Path $dll)){$cs=Join-Path $app 'owned-preflight-page-input.cs';Invoke-WebRequest -UseBasicParsing "+q('http://10.211.55.2:8768/'+name)+" -OutFile $cs;if((Get-FileHash $cs -Algorithm SHA256).Hash-ne "+q(digest.upper())+"){throw 'Helper hash mismatch'};$rect=[System.Windows.Automation.AutomationElement]::RootElement.Current.BoundingRectangle;Add-Type -Path $cs -ReferencedAssemblies @('System.dll','System.Core.dll',$rect.GetType().Assembly.Location,[System.Windows.Automation.AutomationElement].Assembly.Location,[System.Windows.Automation.ControlType].Assembly.Location) -OutputAssembly $dll};Add-Type -Path $dll;"
steps=[('pointer','pointer'),('key','key'),('language','permission-language'),('back','back'),('choose','choose'),('focus-title','title-before'),('language','title-language'),('passive','optional-passive'),('mount','detach'),('mount','remount'),('reduced','reduced')]
code+=r"""function FreshState($test){$limit=[DateTime]::UtcNow.AddSeconds(6);do{try{$file=[IO.File]::Open(($app+'\preflightpage-input.json'),[IO.FileMode]::Open,[IO.FileAccess]::Read,([IO.FileShare]::ReadWrite-bor [IO.FileShare]::Delete));$reader=[IO.StreamReader]::new($file);try{$raw=$reader.ReadToEnd()}finally{$reader.Dispose()};$s=$raw|ConvertFrom-Json;if((& $test $s)){return $raw}}catch{};Start-Sleep -Milliseconds 50}while([DateTime]::UtcNow-lt $limit);throw 'Expected fresh state absent; input must not be repeated'};$records=[Collections.Generic.List[object]]::new();"""
expected={'pointer':'@($s.requests).Count-eq 1','key':'@($s.requests).Count-eq 2','permission-language':'$s.english-and $s.permissionFocused','back':'@($s.requests).Count-eq 3','choose':'@($s.requests).Count-eq 4','title-before':'$s.headingFocused','title-language':'!$s.english-and $s.headingFocused','optional-passive':'!$s.headingFocused-and @($s.requests).Count-eq 4','detach':'!$s.attached','remount':'$s.attached-and $s.opacity-ge 0.999','reduced':'$s.english-and $s.attached-and $s.opacity-ge 0.999'}
if a.remaining_only:
 steps=steps[2:];expected.update({'back':'@($s.requests).Count-eq 1','choose':'@($s.requests).Count-eq 2','optional-passive':'!$s.headingFocused-and @($s.requests).Count-eq 2'})
 code+="$setup=[OwnedPreflightPageInput]::Run($app,'focus-permission');$setup|Set-Content -Encoding UTF8 ($app+'\\preflightpage-remaining-setup.json');$ready=FreshState {param($s) $s.permissionFocused-and @($s.requests).Count-eq 0};"
for mode,label in steps:
 code+="$first=[OwnedPreflightPageInput]::Run($app,"+q(mode)+");$first|Set-Content -Encoding UTF8 ($app+'\\preflightpage-first-"+label+".json');$data=FreshState {param($s) "+expected[label]+"};$state=$data|ConvertFrom-Json;$data|Set-Content -Encoding UTF8 ($app+'\\preflightpage-step-"+label+".json');$records.Add(@{label="+q(label)+";state=$state;firstObservation=($first|ConvertFrom-Json)});"
code+="$records.ToArray()|ConvertTo-Json -Depth 16"
data=ps(code,timeout=60);value=json.loads(data);assert len(value)==len(steps);(a.output/'native-parent-batch.json').write_text(data)
for item in value:(a.output/('native-step-'+item['label']+'.json')).write_text(json.dumps(item['state'],ensure_ascii=False,indent=2))
